'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10H15v-6H9v6H3Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',coach:'M12 3 2 8l10 5 10-5-10-5M5 10v6l7 4 7-4v-6M22 8v7',calendar:'M4 5h16v16H4ZM16 3v4M8 3v4M4 11h16',check:'M9 11l3 3 7-8M20 12v8H4V4h11',book:'M12 5v16M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2',chart:'M4 20V10M10 20V4M16 20v-9M22 20V7',target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l9-9M17 3h4v4',trophy:'M7 3h10v7a5 5 0 0 1-10 0ZM7 5H3v4a4 4 0 0 0 4 4M17 5h4v4a4 4 0 0 1-4 4M12 15v6M8 21h8',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',card:'M3 5h18v14H3ZM3 10h18M6 15h4',spark:'m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3ZM20 2v4M18 4h4',search:'M10 3a7 7 0 1 1 0 14 7 7 0 0 1 0-14M15 15l6 6',plus:'M12 5v14M5 12h14',report:'M6 3h8l4 4v14H6ZM14 3v5h4M9 12h6M9 16h6',game:'M6 7h12l4 11-3 2-5-4h-4l-5 4-3-2ZM7 9v5M5 11h4M16 11h.01M18 13h.01',clock:'M12 3a9 9 0 1 1 0 18 9 9 0 0 1 0-18M12 7v5l3 2',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',arrow:'M5 12h14m-5-5 5 5-5 5',logout:'M9 4H4v16h5M12 12h9m-4-4 4 4-4 4',menu:'M3 6h18M3 12h18M3 18h18',shield:'M12 3 3 6v6c0 5 9 9 9 9s9-4 9-9V6ZM8 12l3 3 5-6'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.home}"/></svg>`;
const btn=(text,action,ico='',style='',id='')=>`<button type="button" class="button ${style}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${ico?icon(ico):''}${esc(text)}</button>`;
const link=(text,page)=>`<button class="link" data-page="${page}">${esc(text)}</button>`;
const avatar=name=>`<span class="avatar">${esc(String(name).split(' ').map(n=>n[0]).slice(0,2).join(''))}</span>`;
const badge=(text,color='')=>`<span class="badge ${color}">${esc(text)}</span>`;
const date=v=>v?new Date(String(v).slice(0,10)+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'—';
const today=()=>new Date().toISOString().slice(0,10);
const num=v=>Number(v||0).toLocaleString('en-IN');
const sum=(arr,key)=>arr.reduce((a,b)=>a+Number(b[key]||0),0);
const avg=(arr,key)=>arr.length?Math.round(sum(arr,key)/arr.length):0;
const empty=(text='No records yet. Your workspace will grow with your students.')=>`<div class="empty">${icon('book')}${esc(text)}</div>`;
const card=(title,content,action='',cls='')=>`<section class="card ${cls}"><div class="card-title"><h2>${esc(title)}</h2>${action}</div>${content}</section>`;
const table=(heads,body)=>body.length?`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${body.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty();
let state={demo:new URLSearchParams(location.search).has('demo'),token:'',me:null,data:null,source:null,page:'dashboard',days:180,search:'',student:null,platform:null};
const admin=()=>state.data?.role==='ORGANIZATION_ADMIN';
const trainer=()=>admin()||state.data?.role==='COACH';
const studentName=id=>state.data.students.find(s=>s.id===id)?.name||'Student';
const coachName=id=>state.data.members.find(s=>s.id===id)?.name||'Unassigned';
const batchName=id=>state.data.batches.find(s=>s.id===id)?.name||'Unassigned';
const observations=(id=null)=>state.data.observations.filter(o=>(!id||o.student_id===id)&&o.practiced_on>=new Date(Date.now()-(state.days-1)*86400000).toISOString().slice(0,10)).sort((a,b)=>a.practiced_on.localeCompare(b.practiced_on)||String(a.created_at).localeCompare(String(b.created_at)));
const history=id=>state.data.observations.filter(o=>o.student_id===id).sort((a,b)=>a.practiced_on.localeCompare(b.practiced_on)||String(a.created_at).localeCompare(String(b.created_at)));
const latest=id=>history(id).at(-1);
const gain=id=>{const h=observations(id);return h.length>1?h.at(-1).rating-h[0].rating:0;};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
async function api(path,method='GET',body){const r=await fetch('/api/v1/academy'+path,{method,headers:{'Content-Type':'application/json',Authorization:'Bearer '+state.token},body:body===undefined?undefined:JSON.stringify(body)});const text=await r.text();let value;try{value=text?JSON.parse(text):null;}catch{throw new Error('Unexpected server response. Check the academy service configuration.');}if(!r.ok)throw new Error(value?.message||'Request failed. Please sign in again if your session expired.');return value;}
function demoScope(){const d=structuredClone(state.source);const role=state.demoRole||'ORGANIZATION_ADMIN';d.role=role;d.memberId=role==='COACH'?'c0':role==='PARENT'?'parent':role==='STUDENT'?'student':'admin';if(role!=='ORGANIZATION_ADMIN'){d.students=d.students.filter(s=>role==='COACH'?s.coach_id==='c0':s.id==='s0');const ids=new Set(d.students.map(s=>s.id));for(const key of ['observations','assignments','reports','games'])d[key]=d[key].filter(s=>ids.has(s.student_id));d.batches=d.batches.filter(b=>d.students.some(s=>s.batch_id===b.id));d.invoices=[];d.seatRequests=[];d.support=[];}state.data=d;}
async function reload(){if(state.demo){demoScope();}else{state.data=await api(`/${state.org}/workspace`);}render();}
function login(){state.data=null;$('#app').innerHTML=`<div class="login"><section class="login-art"><div class="brand"><img class="brand-logo" src="app-icon.png" alt="ChessVerseAI"><div>ChessVerseAI<small>by EpitomeHub</small></div></div><div class="eyebrow">THE ACADEMY WORKSPACE</div><h1>Great coaches.<br>Brighter futures.</h1><p>One home for your students, your coaches, and every next move. Built for chess academies and schools.</p><img class="login-icon" src="app-icon.png" alt="ChessVerseAI king"></section><section class="login-form"><div><h2>Welcome to your academy</h2><p>Sign in with your existing ChessVerse account. Your organization administrator manages your access.</p><form id="login-form"><label>Email or username<input name="identity" required autocomplete="username"></label><label>Password<input name="password" type="password" required maxlength="72" autocomplete="current-password"></label><div class="error" role="alert"></div><button class="button" type="submit">Sign in to workspace ${icon('arrow')}</button></form><div class="separator">TAKE A LOOK AROUND</div>${btn('Explore demo academy','demo','home','secondary')}<p class="small muted">The demo uses synthetic data and resets when you reload.</p></div></section></div>`;}
function nav(){const items=[['dashboard','Dashboard','home'],['label','ACADEMY MANAGEMENT'],['students','Students','users'],...(trainer()?[['coaches','Coaches','coach']]:[]),['batches','Batches & Classes','calendar'],['assignments','Assignments','check'],['reports','Progress Reports','report'],['label','ANALYTICS'],['analytics','Performance Insights','chart'],['weakness','Weakness Analysis','target'],['leaderboard','Leaderboard & Engagement','trophy'],...(admin()?[['label','ORGANIZATION'],['roles','Roles & Permissions','shield'],['billing','Billing & Licensing','card'],['branding','Branding (White Label)','spark'],['support','Support','settings']]:[]),...(state.me.superAdmin&&(!state.demo||admin())?[['label','EPITOMEHUB'],['platform','Super Admin','shield']]:[])];return items.map(([id,label,ico])=>id==='label'?`<div class="nav-label">${label}</div>`:`<button class="nav-item ${(state.page===id||state.page==='profile'&&id==='students')?'active':''}" data-page="${id}">${icon(ico)}${label}</button>`).join('');}
function render(){if(!state.data)return;const d=state.data,o=d.organization;document.documentElement.style.setProperty('--accent',/^#[0-9a-f]{6}$/i.test(o.color)?o.color:'#5754ff');const who=state.demo?(d.role==='COACH'?'Priya Sharma':d.role==='PARENT'?'Mehta family':d.role==='STUDENT'?'Arjun Mehta':'Rohit Verma'):state.me.name;const role=d.role==='ORGANIZATION_ADMIN'?(o.kind==='SCHOOL'?'School Admin':'Academy Admin'):d.role[0]+d.role.slice(1).toLowerCase();const branded=o.white_label;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${o.logo_url?`<img class="brand-logo" src="${esc(o.logo_url)}" alt="Academy logo" referrerpolicy="no-referrer">`:'<img class="brand-logo" src="app-icon.png" alt="ChessVerseAI">'}<div>${branded?esc(o.name):'ChessVerseAI'}<small>${branded?'ACADEMY WORKSPACE':'by EpitomeHub'}</small></div></div><nav aria-label="Main navigation">${nav()}</nav><div class="sidebar-bottom"><div class="upgrade"><strong>♛ &nbsp; Room to grow</strong><p>Build confident players with structured practice and a personal learning journey.</p>${admin()?btn('Manage academy plan','billing','arrow'):btn('View training plans','assignments','arrow')}</div></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button><label class="searchbox">${icon('search')}<input id="global-search" placeholder="Search students, batches, assignments…" aria-label="Search workspace" value="${esc(state.search)}"><kbd>⌘ K</kbd></label><select class="org-select" id="org-select" aria-label="Organization">${state.me.organizations.map(org=>`<option value="${esc(org.id)}" ${org.id===o.id?'selected':''}>♛ &nbsp; ${esc(org.name)}</option>`).join('')}</select><div class="user">${avatar(who)}<div><strong>${esc(who)}</strong><small>${esc(role)}</small></div><button title="Sign out" aria-label="Sign out" data-action="logout">${icon('logout')}</button></div></header>${state.demo?`<div class="demo-notice"><span>DEMO WORKSPACE · Synthetic data · Changes last for this session only</span><label>Preview role &nbsp;<select id="demo-role">${['ORGANIZATION_ADMIN','COACH','STUDENT','PARENT'].map(r=>`<option ${r===d.role?'selected':''}>${r}</option>`).join('')}</select></label></div>`:''}<main class="main" id="main">${page(who)}</main><p class="footnote">${esc(o.name)} · Secure organization workspace · ${state.demo?'Demo data':'Coach-recorded analytics and student-shared games'}</p></div></div>`;}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="toolbar" style="margin:0">${actions}</div></div>`;}
function range(){return `<select class="select" id="date-range" aria-label="Analytics period">${[[7,'Last 7 days'],[30,'Last 30 days'],[180,'Last 6 months']].map(([v,t])=>`<option value="${v}" ${state.days===v?'selected':''}>${t}</option>`).join('')}</select>`;}
function stat(label,value,note,ico){return `<div class="card stat"><span class="stat-icon">${icon(ico)}</span><div><label>${esc(label)}</label><strong>${esc(value)}</strong><small>${esc(note)}</small></div></div>`;}
function chart(obs){if(!obs.length)return empty('No training observations in this period.');const groups=new Map();for(const o of obs){const key=state.days>30?o.practiced_on.slice(0,7):o.practiced_on;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o);}const entries=[...groups.entries()].sort(([a],[b])=>a.localeCompare(b));const max=Math.max(1600,...entries.map(([,v])=>avg(v,'rating')));const x=i=>42+(entries.length===1?.5:i/(entries.length-1))*385;const y=v=>175-v/max*148;const lines=[['rating','#3987ff',1],['accuracy','#22bc91',max/100]];return `<div class="legend">${lines.map(([key,c])=>`<span><i class="dot" style="background:${c}"></i>${{rating:'Average rating',accuracy:'Accuracy %',tactics:'Tactics / session'}[key]}</span>`).join('')}</div><svg class="chart" role="img" aria-label="Rating and accuracy trends" viewBox="0 0 475 210">${[0,1,2,3,4].map(i=>`<line class="grid" x1="42" x2="427" y1="${27+i*37}" y2="${27+i*37}"/><text x="2" y="${31+i*37}">${Math.round(max*(1-i/4))}</text><text x="438" y="${31+i*37}">${100-i*25}%</text>`).join('')}${lines.map(([key,c,factor],j)=>{const points=entries.map(([,v],i)=>`${x(i)},${y(avg(v,key)*factor)}`).join(' ');return `${j===0?`<polygon points="${x(0)},175 ${points} ${x(entries.length-1)},175" fill="#3987ff" opacity=".06"/>`:''}<polyline points="${points}" stroke="${c}" stroke-width="2.2" fill="none"/>${entries.map(([keyDate,v],i)=>`<circle cx="${x(i)}" cy="${y(avg(v,key)*factor)}" r="3" fill="white" stroke="${c}" stroke-width="2"><title>${esc(keyDate)}: ${avg(v,key)} ${key}</title></circle>`).join('')}`;}).join('')}${entries.map(([key],i)=>`<text text-anchor="middle" x="${x(i)}" y="200">${esc(state.days>30?new Date(key+'-15').toLocaleDateString('en',{month:'short'}):key.slice(5))}</text>`).join('')}</svg><p class="chart-caption">Rating: left axis · Accuracy (0–100%): right axis</p>`;}
const weakFields=[['blunders','Tactical blunders','#ff7466'],['opening_errors','Opening knowledge','#ffab72'],['middle_errors','Middlegame planning','#f6ce63'],['endgame_errors','Endgame technique','#59cda5']];
function weakness(obs){const total=weakFields.reduce((n,[key])=>n+sum(obs,key),0);let angle=0;const gradient=weakFields.map(([key,,c])=>{const a=angle;angle+=total?sum(obs,key)/total*100:0;return `${c} ${a}% ${angle}%`;}).join(',');return `<div class="donut-layout"><div class="donut" ${total?`style="background:conic-gradient(${gradient})"`:''}><div class="donut-center"><b>${num(total)}</b><small>Recorded mistakes</small></div></div><div class="weaknesses">${weakFields.map(([key,label,c])=>`<div class="weakness"><i class="dot" style="background:${c}"></i>${label}<b>${total?Math.round(sum(obs,key)/total*100):0}%</b></div>`).join('')}</div></div>`;}
function insights(obs){if(!obs.length)return empty('Record a training session to reveal focus areas.');const weakest=[...weakFields].sort((a,b)=>sum(obs,b[0])-sum(obs,a[0]))[0];const failures=sum(obs,'retry_failures'),attempts=sum(obs,'retry_attempts');const tips=[`Focus the next training plan on ${weakest[1].toLowerCase()}: ${num(sum(obs,weakest[0]))} recorded mistakes.`,attempts?`${Math.round((attempts-failures)/attempts*100)}% of Position Retry attempts succeeded. Revisit failed positions before adding new material.`:'Add Position Retry observations to track improvement.',`Average accuracy is ${avg(obs,'accuracy')}%. Assign a short calculation exercise before the next review.`];return `<div class="insights-list">${tips.map((t,i)=>`<div class="insight"><span class="avatar">${icon(['target','book','spark'][i])}</span><p>${esc(t)}</p></div>`).join('')}</div><p class="chart-caption">Rules-based training suggestions · Coach review recommended</p>`;}
function improving(){return table(['#','Student','Rating','Improvement'],[...state.data.students].filter(s=>history(s.id).length).sort((a,b)=>gain(b.id)-gain(a.id)).slice(0,5).map((s,i)=>[i+1,`<button class="person" data-action="profile" data-id="${esc(s.id)}">${avatar(s.name)}${esc(s.name)}</button>`,num(latest(s.id)?.rating),badge(`${gain(s.id)>=0?'↑ +':'↓ '}${gain(s.id)}`,gain(s.id)>=0?'green':'red')]));}
function activities(){const items=[...state.data.observations.map(o=>({text:`${studentName(o.student_id)} completed a training session`,date:o.created_at,icon:'chart'})),...state.data.assignments.filter(a=>a.completed_at).map(a=>({text:`${studentName(a.student_id)} completed ${a.title}`,date:a.completed_at,icon:'check'})),...state.data.games.map(g=>({text:`${studentName(g.student_id)} shared a game for review`,date:g.created_at,icon:'game'}))].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,5);return items.length?items.map(a=>`<div class="activity"><span class="avatar">${icon(a.icon)}</span><div>${esc(a.text)}<small>${date(a.date)}</small></div></div>`).join(''):empty('Training activity will appear here.');}
function classes(){return state.data.batches.length?`<div class="classes-list">${state.data.batches.slice(0,5).map(b=>`<div class="class-row"><div><strong>${esc(b.name)}</strong><small>${esc(b.schedule)}</small><small>Coach: ${esc(coachName(b.coach_id))}</small></div></div>`).join('')}</div>`:empty('Create your first batch to add a schedule.');}
function quick(){return `<div class="quick-grid">${admin()?btn('Add student','student-form','plus'):btn('Review students','students','users')}${btn('Assign task','assignment-form','check')}${btn('Generate report','report-form','report')}${admin()?btn('Add coach','coach-form','coach'):btn('Record session','observation-form','plus')}</div>`;}
function plan(){const o=state.data.organization,used=state.data.students.filter(s=>s.active).length;return `<div class="plan-info"><span class="crown">♛</span><div><strong>${esc(o.plan)}</strong><small>${used} / ${o.seats} student seats</small></div>${badge(o.status,o.status==='ACTIVE'?'green':'orange')}</div><div class="meter"><span style="width:${Math.min(100,used/o.seats*100)}%"></span></div><span class="small muted">Renewal: ${o.renewal_date?date(o.renewal_date):'Not scheduled'}</span>`;}
function dashboard(who){const d=state.data,obs=observations(),active=new Set(obs.map(o=>o.student_id)).size,isCoach=d.role==='COACH';return heading(`Welcome back, ${who.split(' ')[0]}! 👋`,`Here's what's happening at ${d.organization.name} today.`,range())+`<div class="stats">${stat(isCoach?'Assigned students':'Total students',d.students.length,`${d.students.filter(s=>s.active).length} enabled student accounts`,'users')}${stat('Practicing students',active,'In the selected period','coach')}${stat(isCoach?'Position Retry failures':'Coaches',isCoach?sum(obs,'retry_failures'):d.members.filter(m=>m.role==='COACH'&&m.active).length,isCoach?'From recorded sessions':`Across ${d.batches.length} batches`,'users')}${stat('Shared games',d.games.length,'Student-consented game history','game')}${stat('Training hours',(sum(obs,'minutes')/60).toFixed(1),'Coach-recorded sessions','chart')}</div>${isCoach?card('Students needing attention',attention(),btn('Record session','observation-form','plus'))+'<br>':''}<div class="dashboard-charts">${card('Student Progress Overview',chart(obs),badge('Selected period'))}${card('Weakness Analysis',weakness(obs))}${card('Training Insights',insights(obs),link('View all','weakness'),'insights-card')}</div><div class="dashboard-lower">${card('Top Improving Students',improving(),link('View all','leaderboard'))}${card('Recent Activity',activities(),link('View all','analytics'))}${card('Class Schedules',classes(),link('View all','batches'),'classes-card')}</div><div class="dashboard-bottom"><section class="card hero-banner"><img class="hero-icon" src="app-icon.png" alt="ChessVerseAI"><div><h2>Empowering the Next Generation of Thinkers</h2><p>One student. One breakthrough. One better move.</p></div></section>${trainer()?card('Quick Actions',quick()):card('Your Learning Journey',`<p class="small muted">Practice with purpose. Review your training plan and keep your next goal in sight.</p>${btn('View assignments','assignments','arrow')}`)}${admin()?card('Current Plan',plan(),link('Manage','billing'),'plan-card'):card('Practice Progress',`<div class="metric-row"><div><strong>${d.assignments.filter(a=>a.completed_at).length}</strong><small>Assignments completed</small></div></div>`)}</div>`;}
function attention(){return table(['Student','Rating','Focus area','Retry failures','Action'],state.data.students.filter(s=>latest(s.id)).sort((a,b)=>latest(a.id).accuracy-latest(b.id).accuracy).slice(0,5).map(s=>{const o=latest(s.id),w=[...weakFields].sort((a,b)=>o[b[0]]-o[a[0]])[0];return [`<span class="person">${avatar(s.name)}${esc(s.name)}</span>`,num(o.rating),esc(w[1]),badge(o.retry_failures,o.retry_failures>4?'red':'orange'),btn('View profile','profile','','soft',s.id)];}));}
function studentsPage(){const d=state.data,list=d.students.filter(s=>(s.name+' '+s.email+' '+batchName(s.batch_id)).toLowerCase().includes(state.search.toLowerCase()));return heading('Students','A clear view of every learner and their next step.',admin()?btn('Import CSV','import-form','download','secondary')+btn('Add student','student-form','plus'):'')+card(`All Students (${list.length})`,table(['Student','Batch / Class','Coach','Rating','Status','Actions'],list.map(s=>[`<span class="person">${avatar(s.name)}<span><strong>${esc(s.name)}</strong><br><span class="muted small">${esc(s.email)}</span></span>`,esc(batchName(s.batch_id)),esc(coachName(s.coach_id)),latest(s.id)?num(latest(s.id).rating):'—',badge(s.active?'Active':'Inactive',s.active?'green':''),btn('Profile','profile','','soft',s.id)+(admin()?` <button class="link" data-action="student-form" data-id="${esc(s.id)}">Edit</button>`:'')])));}
function coachesPage(){const coaches=state.data.members.filter(m=>m.role==='COACH');return heading('Coaches','The people guiding your students forward.',admin()?btn('Add coach','coach-form','plus'):'')+`<div class="grid-3">${coaches.map(c=>card(c.name,`${avatar(c.name)}<p class="small muted">${state.data.students.filter(s=>s.coach_id===c.id).length} students · ${state.data.batches.filter(b=>b.coach_id===c.id).length} batches</p>${badge(c.active?'Active':'Inactive',c.active?'green':'')}`)).join('')||empty('No coaches yet.')}</div>`;}
function batchesPage(){const d=state.data,list=d.batches.filter(b=>(b.name+' '+b.schedule).toLowerCase().includes(state.search.toLowerCase()));return heading('Batches & Classes','Manage your chess batches, class schedules and learning outcomes.',admin()?btn('Create new batch','batch-form','plus'):'')+`<div class="stats">${stat('Total batches',d.batches.length,'Across your organization','users')}${stat('Active students',d.students.filter(s=>s.active).length,'Enabled student accounts','coach')}${stat('Coaches assigned',new Set(d.batches.map(b=>b.coach_id).filter(Boolean)).size,'Allocated to batches','users')}${stat('Training sessions',observations().length,'In the selected period','calendar')}${stat('Completion',`${d.assignments.length?Math.round(d.assignments.filter(a=>a.completed_at).length/d.assignments.length*100):0}%`,'Assignment completion','chart')}</div><div class="grid-2">${card(`All Batches (${list.length})`,table(['Batch','Coach','Students','Level',''],list.map(b=>[esc(b.name),esc(coachName(b.coach_id)),d.students.filter(s=>s.batch_id===b.id).length,badge(b.level),admin()?btn('Edit','batch-form','','soft',b.id):'']))) }${card('Class Schedule',classes())}</div><br><div class="grid-3">${list.map(b=>`<section class="card batch-card">${badge(b.level)}<h2>${esc(b.name)}</h2><p>${icon('calendar')} ${esc(b.schedule)}<br>${icon('coach')} ${esc(coachName(b.coach_id))}</p><div class="card-title"><span class="small muted">${d.students.filter(s=>s.batch_id===b.id).length} enrolled students</span>${admin()?btn('Manage','batch-form','','soft',b.id):''}</div></section>`).join('')}</div>`;}
function profile(){const d=state.data,s=d.students.find(s=>s.id===state.student)||d.students[0];if(!s)return heading('Student Analytics','Individual progress, made clear.')+empty('Add a student to view analytics.');state.student=s.id;const obs=observations(s.id),last=latest(s.id),attempts=sum(obs,'retry_attempts'),success=attempts?Math.round((attempts-sum(obs,'retry_failures'))/attempts*100):null,assign=d.assignments.filter(a=>a.student_id===s.id);return heading('Student Profile','Students / '+s.name,range()+(trainer()?btn('Record session','observation-form','plus','',s.id):''))+`<section class="card profile-head">${avatar(s.name)}<div><h2>${esc(s.name)}</h2><p class="small muted">${esc(batchName(s.batch_id))} · Coach ${esc(coachName(s.coach_id))}</p>${badge(s.active?'Active student':'Inactive',s.active?'green':'')}</div></section><div class="stats">${stat('Current rating',last?.rating??'—','Coach recorded · not FIDE','chart')}${stat('Accuracy',last?last.accuracy+'%':'—','Latest training observation','target')}${stat('Shared games',d.games.filter(g=>g.student_id===s.id).length,'Available for review','game')}${stat('Tactics solved',sum(obs,'tactics'),'In the selected period','check')}${stat('Practice streak',streak(s.id)+' days','Consecutive recorded days','clock')}</div><div class="grid-2">${card('Rating & Accuracy Trend',chart(obs))}${card('Next Training Focus',insights(obs),trainer()?btn('AI guidance','guidance','spark','soft',s.id):'')}${card('Common Mistakes',weakness(obs))}${card('Position Retry Performance',`<div class="metric-row"><div><strong>${success===null?'—':success+'%'}</strong><small>Successful retries</small></div><div><strong>${attempts}</strong><small>Total attempts</small></div><div><strong>${sum(obs,'retry_failures')}</strong><small>Still incorrect</small></div></div><div class="callout">${retryImprovement(obs)}</div><p class="small muted">${esc(last?.notes||'Your coach’s feedback will appear here.')}</p>`)}${card('Assigned Training',assignmentList(assign))}${card('Recent Games',gamesList(d.games.filter(g=>g.student_id===s.id)))}</div>`;}
function retryImprovement(obs){if(obs.length<2)return 'Record at least two sessions to compare retry success.';const rate=o=>o.retry_attempts?(o.retry_attempts-o.retry_failures)/o.retry_attempts*100:null;const h=obs.filter(o=>o.retry_attempts);if(h.length<2)return 'More retry observations are needed.';const delta=Math.round(rate(h.at(-1))-rate(h[0]));return `${delta>=0?'+':''}${delta} percentage points in retry success from the first to latest session in this period.`;}
function gamesList(games){return games.length?games.slice(0,10).map(g=>`<div class="activity"><span class="avatar">${icon('game')}</span><div>${esc(studentName(g.student_id))}<small>${esc(g.game_id)} · ${date(g.created_at)}</small></div><button class="link" data-action="game" data-id="${esc(g.id)}">Review</button></div>`).join(''):empty('Students can share their saved computer games with this organization.');}
function gameReview(game){const g=game.state||{},pieces=g.pieces||{},symbols={wK:'♔',wQ:'♕',wR:'♖',wB:'♗',wN:'♘',wP:'♙',bK:'♚',bQ:'♛',bR:'♜',bB:'♝',bN:'♞',bP:'♟'},moves=Array.isArray(g.moves)?g.moves.slice(0,1000):[];return `<button class="close" aria-label="Close" data-action="close">×</button><h2>${esc(g.whiteName||'White')} vs ${esc(g.blackName||'Black')}</h2><p class="intro">${esc(g.result||'Finished game')} · ${moves.length} half-moves · ${state.demo?'Synthetic demo position':'Student-shared game'}</p><div class="game-review-grid"><div><h3>Saved position</h3><div class="review-board" role="img" aria-label="Saved chess position">${Array.from({length:64},(_,i)=>{const file=i%8,rank=8-Math.floor(i/8),square='abcdefgh'[file]+rank;return `<span class="review-square ${(file+rank)%2?'dark':'light'}" title="${square}: ${esc(pieces[square]||'empty')}">${symbols[pieces[square]]||''}</span>`;}).join('')}</div></div><div><h3>Move history</h3>${table(['#','White','Black'],Array.from({length:Math.ceil(moves.length/2)},(_,i)=>[i+1,esc(moves[i*2]),esc(moves[i*2+1]||'—')]))}</div></div><p class="small muted">Review the saved position with your student, then record observations on their profile.</p>`;}
function assignmentList(list){return list.length?list.map(a=>`<section class="card assignment"><div class="details">${badge(a.kind.replaceAll('_',' '))}<h3>${esc(a.title)}</h3><span class="small muted">${esc(studentName(a.student_id))} · Due ${date(a.due_date)}</span><p>${esc(a.instructions)}</p></div>${a.completed_at?badge('Completed','green'):a.due_date<today()?badge('Overdue','red'):badge('In progress','orange')}${!a.completed_at&&(trainer()||state.data.role==='STUDENT')?btn('Mark complete','complete','check','soft',a.id):''}</section>`).join(''):empty('No assignments yet. Start with a focused training goal.');}
function assignmentsPage(){return heading('Assignments & Training Plans','Purposeful practice. Clear goals. Measurable progress.',trainer()?btn('Assign training','assignment-form','plus'):state.data.role==='STUDENT'?btn('Share saved game','share-game-form','game'):'')+assignmentList(state.data.assignments.filter(a=>(a.title+' '+studentName(a.student_id)).toLowerCase().includes(state.search.toLowerCase())));}
function reportsPage(){return heading('Progress Reports','Parent-friendly snapshots of effort, improvement and next steps.',trainer()?btn('Generate report','report-form','plus'):'')+`<div class="grid-2">${card('Weekly & Monthly Reports',`<p class="small muted">Create a dated, immutable snapshot from training observations and assignments. Print to PDF to share with families.</p><div class="callout">Reports describe recorded practice. Missing observations stay missing; they are never estimated.</div>`)}${card('Training Performance',chart(observations()))}</div><br>`+card('Generated Reports',table(['Student','Period','Generated','Export'],state.data.reports.map(r=>[esc(studentName(r.student_id)),badge(r.period),date(r.created_at),btn('Print / PDF','print-report','report','soft',r.id)+' '+btn('CSV','report-csv','download','secondary',r.id)])));}
function streak(id){const days=new Set(history(id).map(o=>o.practiced_on));let n=0,d=new Date(today()+'T12:00:00Z');if(!days.has(d.toISOString().slice(0,10)))d.setUTCDate(d.getUTCDate()-1);while(days.has(d.toISOString().slice(0,10))){n++;d.setUTCDate(d.getUTCDate()-1);}return n;}
function leaderboard(){const batch=state.batchFilter||'';let list=state.data.students.filter(s=>s.active&&(!batch||s.batch_id===batch)).sort((a,b)=>(latest(b.id)?.rating||0)-(latest(a.id)?.rating||0));return heading('Leaderboard & Engagement','Celebrate consistent effort across your learning community.',`<select class="select" id="batch-filter" aria-label="Batch ranking filter"><option value="">All visible batches</option>${state.data.batches.map(b=>`<option value="${esc(b.id)}" ${b.id===batch?'selected':''}>${esc(b.name)}</option>`).join('')}</select>`)+card('Batch Rankings',table(['Rank','Student','Batch','Rating','Improvement','Practice streak','Completed tasks'],list.map((s,i)=>[badge('#'+(i+1),i<3?'orange':''),`<button class="person" data-action="profile" data-id="${esc(s.id)}">${avatar(s.name)}${esc(s.name)}</button>`,esc(batchName(s.batch_id)),latest(s.id)?.rating??'—',badge((gain(s.id)>=0?'+':'')+gain(s.id),'green'),streak(s.id)+' days',state.data.assignments.filter(a=>a.student_id===s.id&&a.completed_at).length])));}
function branding(){const o=state.data.organization;return heading('School / Academy Branding','Make your workspace feel like home.')+`<div class="grid-2">${card('Brand Identity',`<form id="branding-form"><label>Academy / school name<input name="name" maxlength="100" value="${esc(o.name)}" required></label><div class="form-grid"><label>Brand color<input name="color" type="color" value="${esc(o.color)}"></label><label>Logo URL (HTTPS)<input name="logoUrl" type="url" maxlength="500" value="${esc(o.logo_url)}" placeholder="https://your-academy.com/logo.png"></label></div><label><input type="checkbox" name="whiteLabel" ${o.white_label?'checked':''}> Use academy name in the sidebar</label><p class="small muted">White label applies to this portal’s name, logo and accent color. Custom domains and email templates are not part of phase one.</p><div class="error" role="alert"></div><button class="button">Save branding</button></form>`)}${card('Academy Preview',`<div class="branding-preview">${o.logo_url?`<img src="${esc(o.logo_url)}" alt="Academy logo" referrerpolicy="no-referrer">`:'<span style="font-size:42px;color:#f1c864">♛</span>'}<h2>${esc(o.name)}</h2><p class="small muted">Learn · Practice · Excel</p></div><p class="small muted">Brand changes are visible to all members of this organization.</p>`)}</div>`;}
function billing(){return heading('Billing & Licensing','Keep your academy growing with a clear view of seats and subscriptions.',btn('Request seats','seats-form','plus'))+`<div class="grid-3">${card('Your Current Plan',plan())}${card('Seat Requests',state.data.seatRequests.length?state.data.seatRequests.map(r=>`<div class="activity"><div><strong>+${r.seats} seats</strong><small>${date(r.created_at)}</small></div>${badge(r.status,r.status==='APPROVED'?'green':'orange')}</div>`).join(''):empty('No seat requests.'))}${card('Grow Your Academy',`<p class="small muted">Need more room for your next batch? Submit a seat request for EpitomeHub to review.</p>${btn('Request additional seats','seats-form','plus','soft')}<div class="callout">Seat requests do not charge a card. License changes are approved by your EpitomeHub administrator.</div>`)}</div><br>${card('Invoices',table(['Invoice','Issued','Amount','Status','Export'],state.data.invoices.map(i=>[esc(i.label),date(i.issued_on),esc(i.currency)+' '+num(i.amount_minor/100),badge(i.status,i.status==='PAID'?'green':'orange'),btn('Download CSV','invoice-csv','download','secondary',i.id)])))}`;}
function roles(){return heading('Roles & Permissions','The right access for every member of your academy.',btn('Add / update member','member-form','plus'))+card('Organization Members',table(['Member','Email','Role','Access','Edit'],state.data.members.map(m=>[esc(m.name),`<code>${esc(m.email || m.name)}</code>`,badge(m.role.replaceAll('_',' ')),badge(m.active?'Active':'Inactive',m.active?'green':''),btn('Edit','member-form','','soft',m.id)])))+`<br><div class="grid-2">${card('Permission Boundaries',table(['Role','Scope'],[['Super Admin','Organizations, licenses, support, feature flags. No implicit student access.'],['Organization Admin','Manage all students, coaches, batches and settings within their organization.'],['Coach','Assigned students, training observations, assignments and reports.'],['Student','Own analytics, reports, assignments and consenting to share own saved games.'],['Parent','Read-only access to explicitly linked children.']]),'','role-table')}${card('Parent / Child Access',table(['Parent','Child',''],state.data.parentLinks.map(p=>[esc(state.data.members.find(m=>m.id===p.member_id)?.name),esc(studentName(p.student_id)),btn('Unlink','unlink-parent','','secondary',p.member_id+'/'+p.student_id)])),btn('Link parent','parent-form','plus','soft'))}</div>`;}
function support(){return heading('Academy Support','Get help with your organization, access or subscription.',btn('Open support request','support-form','plus'))+card('Support Requests',table(['Subject','Opened','Status'],state.data.support.map(s=>[esc(s.subject),date(s.created_at),badge(s.status,s.status==='CLOSED'?'green':'orange')])));}
function platform(){if(!state.platform)return heading('EpitomeHub Super Admin','Organization operations and licensing.')+btn('Load organizations','load-platform','shield');const p=state.platform;return heading('EpitomeHub Super Admin','All academies and schools · Authorized platform operations',btn('Create organization','organization-form','plus'))+`<div class="stats">${stat('Organizations',p.organizations.length,'Academies and schools','home')}${stat('Active licenses',p.organizations.filter(o=>o.status==='ACTIVE').length,'Current status','shield')}${stat('Student seats used',sum(p.organizations,'students'),'Across organizations','users')}${stat('Shared games',sum(p.organizations,'games'),'Tenant usage','game')}${stat('Open tickets',p.support.filter(s=>s.status==='OPEN').length,'Support requests','report')}</div>`+card('Organizations & Subscriptions',table(['Organization','Type','Plan','Usage','Status','Settings'],p.organizations.map(o=>[esc(o.name),badge(o.kind),esc(o.plan),`${o.students} / ${o.seats} seats`,badge(o.status,o.status==='ACTIVE'?'green':'orange'),btn('License & flags','license-form','','soft',o.id)])))+`<br><div class="grid-2">${card('Seat Requests',table(['Organization','Seats','Status',''],p.seatRequests.map(r=>[esc(p.organizations.find(o=>o.id===r.organization_id)?.name),r.seats,badge(r.status),r.status==='PENDING'?btn('Approve','approve-seats','','soft',r.id):'']))) }${card('Support Queue',table(['Organization','Subject','Status',''],p.support.map(r=>[esc(p.organizations.find(o=>o.id===r.organization_id)?.name),esc(r.subject),badge(r.status),r.status==='OPEN'?btn('Close','close-support','','soft',r.id):''])))}</div>`;}
function page(who){switch(state.page){case 'students':return studentsPage();case 'coaches':return coachesPage();case 'batches':return batchesPage();case 'profile':return profile();case 'assignments':return assignmentsPage();case 'reports':return reportsPage();case 'leaderboard':return leaderboard();case 'branding':return branding();case 'billing':return billing();case 'roles':return roles();case 'support':return support();case 'platform':return platform();case 'analytics':return heading('Performance Insights','Turn training observations into meaningful next steps.',range()+(trainer()?btn('Record session','observation-form','plus'):''))+`<div class="grid-2">${card('Student Progress',chart(observations()))}${card('Training Insights',insights(observations()))}${card('Students Needing Attention',attention())}${card('Recent Shared Games',gamesList(state.data.games))}</div>`;case 'weakness':return heading('Weakness Analysis','Understand the patterns. Practice with intention.',range())+`<div class="grid-2">${card('Mistake Distribution',weakness(observations()))}${card('Training Recommendations',insights(observations()))}</div><br>${card('Student Focus Areas',attention())}`;default:return dashboard(who);}}

const field=(name,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,options,value='',blank=true)=>`<label>${esc(label)}<select name="${name}" ${blank?'':'required'}>${blank?'<option value="">Unassigned</option>':''}${options.map(o=>{const v=Array.isArray(o)?o[0]:o.id,t=Array.isArray(o)?o[1]:o.name;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
const textArea=(name,label,value='',extra='')=>`<label>${esc(label)}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const checkbox=(name,label,checked=true)=>`<label><input name="${name}" type="checkbox" ${checked?'checked':''}> ${esc(label)}</label>`;
function modal(title,intro,fields,form,submit='Save',id=''){const m=$('#modal');m.innerHTML=`<button class="close" aria-label="Close dialog" data-action="close">×</button><h2>${esc(title)}</h2><p class="intro">${esc(intro)}</p><form id="${form}" data-id="${esc(id)}">${fields}<div class="error" role="alert"></div><div class="form-actions">${btn('Cancel','close','','secondary')}<button class="button" type="submit">${esc(submit)}</button></div></form>`;m.showModal();}
async function openForm(action,id){const d=state.data,coaches=d?.members.filter(m=>m.role==='COACH'&&m.active)||[],members=d?.members||[];let item;
  switch(action){
  case 'student-form':item=d.students.find(s=>s.id===id)||{};modal(id?'Edit student':'Add a student','Assign a batch and a personal coach. Student accounts are linked only after membership is granted.',`<div class="form-grid">${field('name','Full name',item.name,'text','required maxlength="100"')}${field('email','Email address',item.email,'email','required maxlength="254"')}${select('batchId','Batch / class',d.batches,item.batch_id)}${select('coachId','Personal coach',coaches,item.coach_id)}</div>${select('accountId','Linked student account (optional)',members.filter(m=>m.role==='STUDENT'&&m.active).map(m=>[m.account_id,m.name]),item.account_id)}${checkbox('active','Active student · uses one seat',item.active??true)}`,'student-form',id?'Save changes':'Add student',id);break;
  case 'batch-form':item=d.batches.find(b=>b.id===id)||{};modal(id?'Manage batch':'Create a new batch','Schedules are displayed exactly as entered. Include days, time and timezone.',field('name','Batch name',item.name,'text','required maxlength="100"')+`<div class="form-grid">${select('level','Level',[['BEGINNER','Beginner'],['INTERMEDIATE','Intermediate'],['ADVANCED','Advanced']],item.level,false)}${select('coachId','Coach',coaches,item.coach_id)}</div>`+field('schedule','Class schedule',item.schedule,'text','required maxlength="200" placeholder="Mon, Wed · 10:00–11:00 IST"'),'batch-form','Save batch',id);break;
  case 'member-form':case 'coach-form':item=members.find(m=>m.id===id)||{};modal(id?'Update member':'Add organization member','Use the email of a verified ChessVerse account. This grants access within this organization only.',field('name','Display name',item.name,'text','required maxlength="100"')+field('email','Verified account email',item.email,'email','required maxlength="254"')+select('role','Role',[['ORGANIZATION_ADMIN','Organization Admin'],['COACH','Coach'],['STUDENT','Student'],['PARENT','Parent']],item.role||(action==='coach-form'?'COACH':'STUDENT'),false)+checkbox('active','Active membership',item.active??true),'member-form','Save membership',id);break;
  case 'assignment-form':modal('Assign a training plan','Assign to one student or a batch. Coaches can assign only to their own students.',select('studentId','Student',d.students.filter(s=>s.active),id)+select('batchId','Or all students in a batch',d.batches)+field('title','Training title','','text','required maxlength="150"')+`<div class="form-grid">${select('kind','Training type',[['PUZZLES','Puzzles'],['POSITIONS','Positions / Retry'],['OPENINGS','Openings'],['MASTER_GAMES','Master games']],'',false)}${field('dueDate','Due date',today(),'date',`required min="${today()}"`)}</div>`+textArea('instructions','Instructions / position FEN / game reference','','required maxlength="2000"'),'assignment-form','Assign training');break;
  case 'observation-form':modal('Record training session','These observations power progress analytics. Use measured values from your review, not estimates.',select('studentId','Student',d.students,id||d.students[0]?.id,false)+`<div class="form-grid">${field('practicedOn','Practice date',today(),'date',`required max="${today()}"`)}${field('rating','Rating',latest(id)?.rating||1200,'number','required min="0" max="4000"')}${field('accuracy','Accuracy (%)','','number','required min="0" max="100"')}${field('minutes','Training minutes','','number','required min="1" max="1440"')}${field('tactics','Tactics solved',0,'number','required min="0" max="10000"')}${field('blunders','Tactical blunders',0,'number','required min="0" max="1000"')}${field('openingErrors','Opening mistakes',0,'number','required min="0" max="1000"')}${field('middleErrors','Middlegame mistakes',0,'number','required min="0" max="1000"')}${field('endgameErrors','Endgame mistakes',0,'number','required min="0" max="1000"')}${field('retryAttempts','Retry attempts',0,'number','required min="0" max="1000"')}${field('retryFailures','Retry failures',0,'number','required min="0" max="1000"')}</div>`+textArea('notes','Coach notes / common mistakes','','maxlength="2000"'),'observation-form','Save session');break;
  case 'report-form':modal('Generate a progress report','Create a stored snapshot for one learner. You can print it to PDF or download its observations as CSV.',select('studentId','Student',d.students,id||d.students[0]?.id,false)+select('period','Reporting period',[['WEEKLY','Weekly · last 7 days'],['MONTHLY','Monthly · past calendar month']],'',false),'report-form','Generate report');break;
  case 'seats-form':modal('Request additional seats','Your EpitomeHub administrator reviews this request. It does not initiate a payment.',field('seats','Additional student seats',10,'number','required min="1" max="10000"'),'seats-form','Submit request');break;
  case 'parent-form':modal('Link a parent to a student','The parent receives read-only access to this child’s analytics, assignments, shared games and reports.',select('memberId','Parent',members.filter(m=>m.role==='PARENT'&&m.active),'',false)+select('studentId','Child',d.students,'',false),'parent-form','Grant read access');break;
  case 'support-form':modal('Open a support request','This request is visible to EpitomeHub platform administrators.',textArea('subject','How can we help?','','required maxlength="200"'),'support-form','Create request');break;
  case 'share-game-form':modal('Share your saved game','Choose a recent saved computer game. Your academy admin, assigned coach and linked parents can review the game you share.',select('gameId','Your saved game',state.demo?[['demo-game','Demo practice game · White vs Black']]:await api(`/${state.org}/shareable-games`),'',false),'share-game-form','Share with academy');break;
  case 'import-form':modal('Import students','Upload a UTF-8 CSV with name,email columns. Optional batch and coach columns must exactly match existing names. All rows are validated; live imports are atomic.',`<label>CSV file<input name="csv" type="file" accept=".csv,text/csv" required></label><div class="callout">name,email,batch,coach<br>Arjun Mehta,arjun@example.com,Beginners A,Priya Sharma<br><br>Maximum 200 students. Imported students are active; no login access is granted until an account is linked.</div>`,'import-form','Import students');break;
  case 'organization-form':modal('Create an academy or school','Provision an organization for an existing verified account. The account owner becomes Organization Admin.',field('name','Organization name','','text','required maxlength="100"')+select('kind','Organization type',[['ACADEMY','Chess academy'],['SCHOOL','School']],'',false)+field('adminAccountId','Administrator account UUID','','text','required pattern="[0-9a-fA-F-]{36}"'),'organization-form','Create organization');break;
  case 'license-form':item=state.platform.organizations.find(o=>o.id===id);modal('License & feature flags',item.name+' · Changes apply immediately to this organization.',field('plan','Plan name',item.plan,'text','required maxlength="60"')+`<div class="form-grid">${field('seats','Total seat limit',item.seats,'number','required min="1" max="100000"')}${field('renewalDate','Renewal date',item.renewal_date||today(),'date','required')}${select('status','Status',[['TRIAL','Trial'],['ACTIVE','Active'],['SUSPENDED','Suspended']],item.status,false)}</div>`+field('featureFlags','Feature flags (operational metadata)',item.feature_flags,'text','maxlength="1000"')+'<p class="small muted">Flags are stored for rollout planning. They do not bypass role permissions or enable unimplemented features.</p>','license-form','Update license',id);break;
  }
}
function parseCsv(text){const result=[];let row=[],cell='',quoted=false,closed=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++;}else{quoted=false;closed=true;}}else cell+=c;}else if(c==='"'){if(cell||closed)throw new Error('Invalid CSV quote.');quoted=true;}else if(c===','||c==='\n'||c==='\r'){row.push(cell.trim());cell='';closed=false;if(c!==','){if(c==='\r'&&text[i+1]==='\n')i++;if(row.some(Boolean))result.push(row);row=[];}}else{if(closed&&!/\s/.test(c))throw new Error('Unexpected content after CSV quote.');cell+=c;}}if(quoted)throw new Error('CSV contains an unclosed quote.');row.push(cell.trim());if(row.some(Boolean))result.push(row);if(result.length<2)throw new Error('CSV must include a header and at least one student.');const headers=result.shift().map(h=>h.replace(/^\uFEFF/,'').toLowerCase());if(new Set(headers).size!==headers.length||!headers.includes('name')||!headers.includes('email')||headers.some(h=>!['name','email','batch','coach'].includes(h)))throw new Error('Use unique name,email,batch,coach column headers.');if(result.length>200)throw new Error('Import at most 200 students at once.');return result.map((r,i)=>{if(r.length!==headers.length)throw new Error(`Row ${i+2}: wrong number of columns.`);return Object.fromEntries(headers.map((h,j)=>[h,r[j]]));});}
function importPayload(rows){const emails=new Set(state.data.students.map(s=>s.email.toLowerCase()));const lookup=(list,name,label)=>{if(!name)return null;const matches=list.filter(x=>x.name.toLowerCase()===name.toLowerCase());if(matches.length!==1)throw new Error(`${label} "${name}" is missing or ambiguous.`);return matches[0].id;};const students=rows.map((r,i)=>{if(!r.name||r.name.length>100||r.email.length>254||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email))throw new Error(`Row ${i+2}: provide a valid name and email.`);const email=r.email.toLowerCase();if(emails.has(email))throw new Error(`Duplicate student email: ${email}`);emails.add(email);return {name:r.name,email,batchId:lookup(state.data.batches,r.batch,'Batch'),coachId:lookup(state.data.members.filter(m=>m.role==='COACH'&&m.active),r.coach,'Coach'),accountId:null,active:true};});if(state.data.students.filter(s=>s.active).length+students.length>state.data.organization.seats)throw new Error('Not enough licensed seats for this import.');return {students};}
function download(name,rows){const csv=rows.map(r=>r.map(v=>{let t=String(v??'');if(/^[\s]*[=+\-@\t\r]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"';}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function reportData(id){const r=state.data.reports.find(r=>r.id===id);return {record:r,...JSON.parse(r.summary)};}
function printReport(id){const r=reportData(id),obs=r.observations,attempts=sum(obs,'retry_attempts');$('#print-report').innerHTML=`<h1>${esc(state.data.organization.name)}</h1><p>Student Progress Report · ${esc(r.record.period)}</p><hr><h2>${esc(r.student)}</h2><p>${date(r.from)} – ${date(r.to)}</p><p>${esc(r.source)}. ${state.demo?'DEMO REPORT — synthetic data.':''}</p><div class="metric-row"><div><strong>${(sum(obs,'minutes')/60).toFixed(1)} hours</strong><small>Training time</small></div><div><strong>${obs.length?avg(obs,'accuracy')+'%':'No data'}</strong><small>Average accuracy</small></div><div><strong>${sum(obs,'tactics')}</strong><small>Tactics solved</small></div><div><strong>${attempts?Math.round((attempts-sum(obs,'retry_failures'))/attempts*100)+'%':'No data'}</strong><small>Retry success</small></div></div><h2>Training Journey</h2>${table(['Practice date','Rating','Accuracy','Minutes','Coach feedback'],obs.map(o=>[date(o.practiced_on),o.rating,o.accuracy+'%',o.minutes,esc(o.notes)]))}<h2>Assigned Practice</h2>${table(['Training','Due','Status'],r.assignments.map(a=>[esc(a.title),date(a.due_date),a.completed_at?'Completed':'In progress']))}<h2>What to practice next</h2><p>${obs.length?esc([...weakFields].sort((a,b)=>sum(obs,b[0])-sum(obs,a[0]))[0][1])+': ask your coach for a focused practice plan.':'More observations are needed before suggesting a training focus.'}</p><p>Ratings and observations are recorded by the coach. This report does not certify an official chess rating.</p><hr><p>Prepared ${date(r.record.created_at)} · ChessVerseAI by EpitomeHub</p>`;window.print();}
async function loadPlatform(){state.platform=state.demo?{organizations:[{...state.source.organization,students:state.source.students.filter(s=>s.active).length,games:state.source.games.length}],support:state.source.support,seatRequests:state.source.seatRequests}:await api('/platform');state.page='platform';if(state.data)render();else renderNoOrg();}
function renderNoOrg(){document.documentElement.style.setProperty('--accent','#5754ff');$('#app').innerHTML=`<main class="main">${heading('Your Academy Workspace',`Signed in as ${state.me.name}`,btn('Sign out','logout','logout','secondary'))}${state.me.superAdmin?platform():card('No organization membership yet',`<p class="small muted">Ask your academy or school administrator to add your verified ChessVerse email. If you are setting up a new academy, contact EpitomeHub for provisioning.</p>` )}</main>`;}
async function start(){if(state.demo){state.source=window.createAcademyDemo();state.me={name:'Rohit Verma',superAdmin:true,organizations:[state.source.organization]};state.org='demo';demoScope();render();}else{state.me=await api('/me');state.org=state.me.organizations[0]?.id;if(state.org)await reload();else renderNoOrg();}}
function demoWrite(kind,i,id){const d=state.source,newId=()=>crypto.randomUUID(),stamp=new Date().toISOString();const snake=o=>Object.fromEntries(Object.entries(o).map(([k,v])=>[k.replace(/[A-Z]/g,c=>'_'+c.toLowerCase()),v]));const upsert=(key,value)=>{const index=d[key].findIndex(v=>v.id===id);if(index<0)d[key].push({id:newId(),created_at:stamp,...value});else d[key][index]={...d[key][index],...value};};switch(kind){case 'student-form':if(i.active&&!d.students.find(s=>s.id===id)?.active&&d.students.filter(s=>s.active).length>=d.organization.seats)throw new Error('Seat limit reached.');if(d.students.some(s=>s.id!==id&&s.email.toLowerCase()===i.email.toLowerCase()))throw new Error('Student email already exists.');upsert('students',snake(i));break;case 'batch-form':upsert('batches',snake(i));break;case 'member-form':upsert('members',{...i,account_id:id||newId()});break;case 'assignment-form':i.studentIds.forEach(student_id=>d.assignments.push({id:newId(),student_id,title:i.title,kind:i.kind,instructions:i.instructions,due_date:i.dueDate,created_at:stamp,completed_at:null}));break;case 'observation-form':d.observations.push({id:newId(),created_at:stamp,...snake(i)});break;case 'report-form':{const end=new Date(today()+'T12:00:00Z'),start=new Date(end);if(i.period==='WEEKLY')start.setUTCDate(start.getUTCDate()-6);else{const month=start.getUTCMonth();start.setUTCMonth(month-1);if(start.getUTCMonth()===month)start.setUTCDate(0);start.setUTCDate(start.getUTCDate()+1);}const from=start.toISOString().slice(0,10),to=today();d.reports.push({id:newId(),student_id:i.studentId,period:i.period,created_at:stamp,summary:JSON.stringify({student:studentName(i.studentId),from,to,source:'Coach-recorded training observations',observations:d.observations.filter(o=>o.student_id===i.studentId&&o.practiced_on>=from&&o.practiced_on<=to).sort((a,b)=>a.practiced_on.localeCompare(b.practiced_on)),assignments:d.assignments.filter(a=>a.student_id===i.studentId&&a.due_date>=from&&a.due_date<=to)})});break;}case 'branding-form':Object.assign(d.organization,snake(i));break;case 'seats-form':d.seatRequests.push({id:newId(),organization_id:'demo',seats:i.seats,status:'PENDING',created_at:stamp});break;case 'parent-form':if(!d.parentLinks.some(p=>p.member_id===i.memberId&&p.student_id===i.studentId))d.parentLinks.push(snake(i));break;case 'support-form':d.support.push({id:newId(),organization_id:'demo',subject:i.subject,status:'OPEN',created_at:stamp});break;case 'import-form':i.students.forEach(s=>upsert('students',snake(s)));break;case 'license-form':Object.assign(d.organization,snake(i));break;case 'organization-form':throw new Error('Organization provisioning is available in the live portal. Sign in with platform access.');case 'share-game-form':throw new Error('Sign in to share a real saved game.');}}
document.addEventListener('click',async e=>{const node=e.target.closest('[data-action],[data-page]');if(!node)return;try{if(node.dataset.page){state.page=node.dataset.page;state.search='';state.batchFilter='';render();window.scrollTo(0,0);return;}const a=node.dataset.action,id=node.dataset.id;if(a==='close'){$('#modal').close();return;}if(a==='demo'){state.demo=true;window.history.replaceState(null,'',location.pathname+'?demo');await start();return;}if(a==='logout'){state.token='';state.me=null;state.platform=null;state.source=null;state.demo=false;state.page='dashboard';window.history.replaceState(null,'',location.pathname);login();return;}if(a==='menu'){$('.shell').classList.toggle('nav-open');return;}if(a==='profile'){state.student=id;state.page='profile';render();return;}if(['students','billing','assignments'].includes(a)){state.page=a;render();return;}if(a.endsWith('-form')){await openForm(a,id);return;}if(a==='load-platform'){await loadPlatform();return;}if(a==='print-report'){printReport(id);return;}if(a==='report-csv'){const r=reportData(id);download('student-progress.csv',[['Student','Date','Rating','Accuracy','Minutes','Tactics','Retry attempts','Retry failures','Coach notes'],...r.observations.map(o=>[r.student,o.practiced_on,o.rating,o.accuracy,o.minutes,o.tactics,o.retry_attempts,o.retry_failures,o.notes])]);return;}if(a==='invoice-csv'){const i=state.data.invoices.find(i=>i.id===id);download('invoice.csv',[['Invoice','Date','Amount','Currency','Status'],[i.label,i.issued_on,i.amount_minor/100,i.currency,i.status]]);return;}node.disabled=true;
if(a==='game'){const game=state.demo?{state:{whiteName:'Demo student',blackName:'Practice opponent',result:'Demo position',level:3,pieces:{e1:'wK',d4:'wP',e8:'bK',f6:'bP'},moves:['e4','e5','Nf3','Nc6']}}:await api(`/${state.org}/games/${encodeURIComponent(id)}`);const m=$('#modal');m.innerHTML=gameReview(game);m.showModal();return;}
if(a==='guidance'){const guidance=state.demo?{source:'RULES',text:'Demo guidance: review three endgame mistakes, practice five king-and-pawn positions, then retry after 48 hours. Live AI guidance uses only numeric training evidence and requires a configured provider.'}:await api(`/${state.org}/students/${id}/guidance`,'POST');const m=$('#modal');m.innerHTML=`<button class="close" aria-label="Close" data-action="close">×</button><h2>${guidance.source==='AI'?'AI Training Recommendations':'Training Guidance'}</h2><p class="intro">${guidance.source==='AI'?'AI-generated from the last 30 days of recorded sessions. Review before assigning.':'Rules-based fallback · No AI output was generated.'}</p><p class="small" style="white-space:pre-wrap">${esc(guidance.text)}</p>`;m.showModal();return;}
if(a==='complete'){if(state.demo)state.source.assignments.find(x=>x.id===id).completed_at=new Date().toISOString();else await api(`/${state.org}/assignments/${id}/complete`,'POST');await reload();toast('Assignment completed.');}
if(a==='unlink-parent'){if(state.demo){const [member,student]=id.split('/');state.source.parentLinks=state.source.parentLinks.filter(p=>p.member_id!==member||p.student_id!==student);}else await api(`/${state.org}/parent-links/${id}`,'DELETE');await reload();toast('Parent access removed.');}
if(a==='approve-seats'||a==='close-support'){if(state.demo){const row=(a==='approve-seats'?state.source.seatRequests:state.source.support).find(r=>r.id===id);if(a==='approve-seats'){state.source.organization.seats+=row.seats;row.status='APPROVED';}else row.status='CLOSED';}else await api(`/platform/${a==='approve-seats'?'seat-requests':'support'}/${id}/${a==='approve-seats'?'approve':'close'}`,'POST');await loadPlatform();toast('Request updated.');}
}catch(err){toast(err.message);}finally{node.disabled=false;}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button[type="submit"],button.button:not([data-action])'),error=form.querySelector('.error');if(button)button.disabled=true;if(error)error.textContent='';try{const f=new FormData(form),v=Object.fromEntries(f),id=form.dataset.id;let body,path,method='POST';const nullable=k=>v[k]||null;
if(form.id==='login-form'){const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)});const response=await r.json();if(!r.ok)throw new Error(response.message||'Unable to sign in.');state.token=response.token;await start();return;}
switch(form.id){case 'student-form':body={name:v.name,email:v.email,accountId:nullable('accountId'),batchId:nullable('batchId'),coachId:nullable('coachId'),active:f.has('active')};path='students'+(id?'/'+id:'');method=id?'PUT':'POST';break;case 'batch-form':body={...v,coachId:nullable('coachId')};path='batches'+(id?'/'+id:'');method=id?'PUT':'POST';break;case 'member-form':body={...v,active:f.has('active')};path='members';break;case 'parent-form':body=v;path='parent-links';break;case 'assignment-form':if((!v.studentId&&!v.batchId)||(v.studentId&&v.batchId))throw new Error('Choose one student or one batch.');body={title:v.title,kind:v.kind,instructions:v.instructions,dueDate:v.dueDate,studentIds:v.studentId?[v.studentId]:state.data.students.filter(s=>s.active&&s.batch_id===v.batchId).map(s=>s.id)};if(!body.studentIds.length)throw new Error('No active assigned students in this batch.');path='assignments';break;case 'observation-form':body={...v};for(const k of ['rating','accuracy','minutes','tactics','blunders','openingErrors','middleErrors','endgameErrors','retryAttempts','retryFailures'])body[k]=Number(v[k]);if(body.retryFailures>body.retryAttempts)throw new Error('Retry failures cannot exceed attempts.');path='observations';break;case 'report-form':body=v;path='reports';break;case 'branding-form':body={...v,whiteLabel:f.has('whiteLabel')};path='branding';method='PUT';break;case 'seats-form':body={seats:Number(v.seats)};path='seat-requests';break;case 'support-form':body=v;path='support';break;case 'share-game-form':body={};path='games/'+encodeURIComponent(v.gameId)+'/share';break;case 'import-form':{const file=f.get('csv');if(file.size>500000)throw new Error('CSV must be smaller than 500 KB.');body=importPayload(parseCsv(await file.text()));path='students/import';break;}case 'organization-form':body=v;path='/platform/organizations';break;case 'license-form':body={...v,seats:Number(v.seats)};path='/platform/organizations/'+id+'/license';method='PUT';break;default:return;}
if(state.demo)demoWrite(form.id,body,id);else await api(path.startsWith('/')?path:`/${state.org}/${path}`,method,body);if($('#modal').open)$('#modal').close();if(path.startsWith('/platform'))await loadPlatform();else{if(form.id==='report-form')state.page='reports';await reload();}toast(form.id==='seats-form'?'Seat request submitted. No payment was taken.':state.demo?'Updated demo workspace. Changes reset on reload.':'Saved successfully.');
}catch(err){if(error)error.textContent=err.message;else toast(err.message);}finally{if(button)button.disabled=false;}});
document.addEventListener('change',async e=>{try{if(e.target.id==='date-range'){state.days=Number(e.target.value);render();}if(e.target.id==='batch-filter'){state.batchFilter=e.target.value;render();}if(e.target.id==='demo-role'){state.demoRole=e.target.value;state.page='dashboard';state.student=null;demoScope();render();}if(e.target.id==='org-select'){state.org=e.target.value;state.data=null;state.student=null;state.search='';state.page='dashboard';state.platform=null;$('#main').innerHTML=empty('Loading organization…');await reload();}}catch(err){state.data=null;$('#main').innerHTML=empty(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='global-search'){state.search=e.target.value;if(!['students','assignments','batches'].includes(state.page))state.page='students';$('#main').innerHTML=page(state.me.name);document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===state.page));}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#global-search')?.focus();}});
if(!window.__ACADEMY_TEST__){if(state.demo)start().catch(e=>{login();toast(e.message);});else login();}
